pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    uint256 constant INITIAL_MIN_SUM = 1 ether;

    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint96 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);
        assertTrue(c.MinSum() == INITIAL_MIN_SUM);
    }
}
